package com.himorning.android.ui

import com.himorning.android.R
import com.himorning.android.core.*

internal fun preferredMode(kind: ChallengeKind) = when (kind) { ChallengeKind.PUSH_UPS, ChallengeKind.JUMPING_JACKS, ChallengeKind.STRETCHING -> WakeMode.FOCUSED; ChallengeKind.READ_ALOUD, ChallengeKind.READ_AND_CHOOSE, ChallengeKind.RIDDLE -> WakeMode.BALANCED; else -> WakeMode.GENTLE }
internal fun modeText(mode: WakeMode) = when (mode) { WakeMode.GENTLE -> R.string.gentle; WakeMode.BALANCED -> R.string.balanced; WakeMode.FOCUSED -> R.string.focused }
internal fun stateText(state: ScheduleState) = when (state) { ScheduleState.PENDING -> R.string.pending; ScheduleState.CONFIRMED -> R.string.confirmed; ScheduleState.OFF -> R.string.off; ScheduleState.NEEDS_REVIEW -> R.string.needs_review }
internal fun challengeText(kind: ChallengeKind) = when (kind) { ChallengeKind.NONE -> R.string.none; ChallengeKind.PUSH_UPS -> R.string.push_ups; ChallengeKind.READ_AND_CHOOSE -> R.string.read_and_choose; ChallengeKind.GUIDED_RHYTHM -> R.string.guided_rhythm; ChallengeKind.READ_ALOUD -> R.string.read_aloud; ChallengeKind.WAVE_HAND -> R.string.wave_hand; ChallengeKind.NECK_ROTATION -> R.string.neck_rotation; ChallengeKind.RIDDLE -> R.string.riddle; ChallengeKind.JUMPING_JACKS -> R.string.jumping_jacks; ChallengeKind.STRETCHING -> R.string.stretching }
internal fun soundText(sound: AlarmSound) = when (sound) { AlarmSound.SYSTEM -> R.string.system; AlarmSound.SUNRISE -> R.string.sunrise; AlarmSound.SOFT_CHIME -> R.string.soft_chime; AlarmSound.PIZZICATO_DAWN -> R.string.pizzicato_dawn; AlarmSound.PIZZICATO_STEPS -> R.string.pizzicato_steps; AlarmSound.PIZZICATO_RISE -> R.string.pizzicato_rise; AlarmSound.PIZZICATO_BLOOM -> R.string.pizzicato_bloom; AlarmSound.STEEL_SHIMMER -> R.string.steel_shimmer; AlarmSound.STEEL_BREEZE -> R.string.steel_breeze; AlarmSound.STEEL_MORNING -> R.string.steel_morning; AlarmSound.STEEL_SPARKLE -> R.string.steel_sparkle; AlarmSound.SAX_HELLO -> R.string.sax_hello; AlarmSound.SAX_STROLL -> R.string.sax_stroll; AlarmSound.SAX_GLOW -> R.string.sax_glow; AlarmSound.SAX_DAYBREAK -> R.string.sax_daybreak }
internal fun focusText(focus: MorningFocus) = when (focus) { MorningFocus.CLEAR_START -> R.string.clear_start; MorningFocus.GENTLE_MOVEMENT -> R.string.gentle_movement; MorningFocus.FIND_YOUR_VOICE -> R.string.find_your_voice; MorningFocus.ENERGIZE -> R.string.energize }
internal fun guideText(kind: ChallengeKind) = when (kind) { ChallengeKind.PUSH_UPS -> R.string.guide_push_ups; ChallengeKind.WAVE_HAND -> R.string.guide_wave_hand; ChallengeKind.NECK_ROTATION -> R.string.guide_neck_rotation; ChallengeKind.JUMPING_JACKS -> R.string.guide_jumping_jacks; ChallengeKind.STRETCHING -> R.string.guide_stretching; else -> R.string.guide_guided_rhythm }
